/**
 * Google Search Console — read-only OAuth integration.
 *
 * Powers "SEO Opportunity Discovery" (striking-distance queries: real search
 * volume, ranking outside the top 10, no page winning it yet). This module
 * NEVER writes to Google — it only reads via the `webmasters.readonly` scope
 * (searchanalytics.query + sites.list) and exchanges/refreshes OAuth tokens.
 * Findings are written only to our own DB, by worker/seo.ts.
 *
 * No `googleapis` package — it isn't installed and isn't worth adding for one
 * API surface. Plain `fetch` against Google's documented REST endpoints.
 *
 * Credentials come from env (GSC_OAUTH_CLIENT_ID / GSC_OAUTH_CLIENT_SECRET /
 * GSC_OAUTH_REDIRECT_URI), same as every other OAuth client in this codebase
 * (see lib/cloudflare-oauth.ts) — provisioned once in /etc/nxeon and copied
 * into each environment's own .env (prod keeps the nxeon.cloud redirect URI,
 * staging carries its own staging.nxeon.cloud one). Never hardcode either URI.
 *
 * This is a PLATFORM-WIDE singleton connection (one Search Console account for
 * the whole site), not a per-customer one — see `GscConnection` in the Prisma
 * schema, gated behind the "platform" admin area (ADMIN role only).
 */

import { db } from "../db";
import { encryptSecret, decryptSecret } from "../crypto-box";

const OAUTH_AUTHORIZE_URL = "https://accounts.google.com/o/oauth2/v2/auth";
const OAUTH_TOKEN_URL = "https://oauth2.googleapis.com/token";
const USERINFO_URL = "https://openidconnect.googleapis.com/v1/userinfo";
const SC_API_BASE = "https://www.googleapis.com/webmasters/v3";

/**
 * Scope requested at consent. `webmasters.readonly` is the scope the OAuth
 * client is actually published/reviewed for (non-sensitive, no verification
 * needed) — it is the ONLY scope that unlocks the Search Console API calls
 * below. `email` (a basic, non-sensitive identity scope every Google OAuth
 * client may request without extra consent-screen configuration) is added
 * alongside it purely so the callback can show "Connected as {email}" in the
 * admin UI; it grants no extra access to anything else and nothing here reads
 * profile/name data. If a live test ever shows Google rejecting the combined
 * scope, drop " email" and the connection still works — accountEmail just
 * falls back to a placeholder (see fetchAccountEmail below).
 */
const SCOPE = "https://www.googleapis.com/auth/webmasters.readonly email";

function clientId(): string {
  return (process.env.GSC_OAUTH_CLIENT_ID ?? "").trim();
}
function clientSecret(): string {
  return (process.env.GSC_OAUTH_CLIENT_SECRET ?? "").trim();
}
function redirectUri(): string {
  return (process.env.GSC_OAUTH_REDIRECT_URI ?? "").trim();
}

/** Is the OAuth client configured in this environment? Gates the UI's Connect button. */
export function gscConfigured(): boolean {
  return Boolean(clientId() && clientSecret() && redirectUri());
}

// ---------------------------------------------------------------------------
// Step 1: consent URL
// ---------------------------------------------------------------------------

/**
 * Build the Google OAuth consent URL. `access_type=offline` + `prompt=consent`
 * are both required to get a REFRESH token back (not just a short-lived access
 * token) — omitting either one means Google may silently skip issuing one on a
 * repeat consent.
 */
export function gscAuthorizeUrl(state: string): string {
  const url = new URL(OAUTH_AUTHORIZE_URL);
  url.searchParams.set("response_type", "code");
  url.searchParams.set("client_id", clientId());
  url.searchParams.set("redirect_uri", redirectUri());
  url.searchParams.set("scope", SCOPE);
  url.searchParams.set("access_type", "offline");
  url.searchParams.set("prompt", "consent");
  url.searchParams.set("state", state);
  return url.toString();
}

// ---------------------------------------------------------------------------
// Step 2/3: token endpoint (exchange + refresh)
// ---------------------------------------------------------------------------

type TokenResponse = {
  access_token?: string;
  refresh_token?: string;
  expires_in?: number;
  scope?: string;
  token_type?: string;
  error?: string;
  error_description?: string;
};

async function tokenRequest(params: Record<string, string>): Promise<{ token?: TokenResponse; error?: string }> {
  let res: Response;
  try {
    res = await fetch(OAUTH_TOKEN_URL, {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded", Accept: "application/json" },
      body: new URLSearchParams({
        ...params,
        client_id: clientId(),
        client_secret: clientSecret(),
      }).toString(),
      cache: "no-store",
    });
  } catch {
    return { error: "Couldn't reach Google to finish connecting. Try again shortly." };
  }
  let parsed: TokenResponse | null = null;
  try {
    parsed = (await res.json()) as TokenResponse;
  } catch {
    parsed = null;
  }
  if (!res.ok || !parsed?.access_token) {
    const detail = parsed?.error_description || parsed?.error || `HTTP ${res.status}`;
    return { error: `Google rejected the connection (${String(detail).slice(0, 160)}).` };
  }
  return { token: parsed };
}

/** Exchange an authorization code for tokens. Returns the refresh token IF Google issued one. */
export async function gscExchangeCode(
  code: string,
): Promise<{ accessToken?: string; refreshToken?: string; error?: string }> {
  const { token, error } = await tokenRequest({
    grant_type: "authorization_code",
    code,
    redirect_uri: redirectUri(),
  });
  if (!token) return { error };
  return { accessToken: token.access_token, refreshToken: token.refresh_token };
}

/** Trade a stored refresh token for a fresh access token. */
export async function gscRefreshAccessToken(refreshToken: string): Promise<{ accessToken?: string; error?: string }> {
  const { token, error } = await tokenRequest({
    grant_type: "refresh_token",
    refresh_token: refreshToken,
  });
  if (!token) return { error };
  return { accessToken: token.access_token };
}

/**
 * Best-effort connected-account email, for display only ("Connected as …").
 * Never blocks storing the connection — a failure here (e.g. the `email`
 * scope wasn't actually granted) just falls back to a generic label.
 */
export async function gscFetchAccountEmail(accessToken: string): Promise<string | null> {
  try {
    const res = await fetch(USERINFO_URL, {
      headers: { Authorization: `Bearer ${accessToken}` },
      cache: "no-store",
    });
    if (!res.ok) return null;
    const data = (await res.json()) as { email?: string };
    return data.email ?? null;
  } catch {
    return null;
  }
}

// ---------------------------------------------------------------------------
// Search Console REST calls
// ---------------------------------------------------------------------------

export type GscSiteEntry = { siteUrl: string; permissionLevel: string };

/**
 * List every Search Console property this account can see. The reliable way
 * to learn whether nxeon.cloud is verified as a DOMAIN property
 * (`sc-domain:nxeon.cloud`) or a URL-PREFIX property (`https://nxeon.cloud/`)
 * — guessing the siteUrl path segment and getting the encoding wrong is the
 * most common way this API 404s.
 */
export async function gscListSites(accessToken: string): Promise<{ sites?: GscSiteEntry[]; error?: string }> {
  let res: Response;
  try {
    res = await fetch(`${SC_API_BASE}/sites`, {
      headers: { Authorization: `Bearer ${accessToken}` },
      cache: "no-store",
    });
  } catch {
    return { error: "Couldn't reach the Search Console API." };
  }
  if (!res.ok) {
    const body = await res.text().catch(() => "");
    return { error: `Search Console sites.list failed (HTTP ${res.status}): ${body.slice(0, 200)}` };
  }
  const data = (await res.json().catch(() => null)) as { siteEntry?: GscSiteEntry[] } | null;
  return { sites: data?.siteEntry ?? [] };
}

/**
 * Pick the verified property for our own domain out of a sites.list response.
 * Prefers the domain property (covers http/https + all subdomains) over a
 * URL-prefix property, since that's the stronger verification Search Console
 * offers; falls back to any entry that mentions the apex domain.
 */
export function resolveSiteUrl(sites: GscSiteEntry[], apexDomain = "nxeon.cloud"): string | null {
  const verified = sites.filter((s) => s.permissionLevel && s.permissionLevel !== "siteUnverifiedUser");
  const domainProp = verified.find((s) => s.siteUrl === `sc-domain:${apexDomain}`);
  if (domainProp) return domainProp.siteUrl;
  const prefixProp = verified.find((s) => s.siteUrl.includes(apexDomain));
  if (prefixProp) return prefixProp.siteUrl;
  // No verified match — fall back to ANY entry mentioning the domain, in case
  // permissionLevel comes back in a shape we didn't anticipate.
  return sites.find((s) => s.siteUrl.includes(apexDomain))?.siteUrl ?? null;
}

