/**
 * SEO Opportunity Discovery — DISCOVERY SWEEP (worker task, weekly).
 *
 * For the connected Google Search Console property it:
 *   1. Refreshes an access token from the stored (encrypted) refresh token.
 *   2. Pulls the last ~90 days of query+page data — read-only, one API call.
 *   3. Filters to real search volume (impressions >= a tunable threshold)
 *      ranking outside the top 10 (11–30 — the realistic content-gap zone).
 *   4. Upserts the result into SeoOpportunity — a re-run UPDATES the existing
 *      row's metrics + lastSeenAt rather than duplicating it.
 *
 * CRITICAL: this sweep NEVER writes to Google. It only calls the authorized
 * read-only Search Console API and writes to our own DB. A human reviews the
 * list at /admin/seo and marks rows REVIEWED/ACTIONED/DISMISSED themselves.
 * See lib/seo/searchConsole.ts (OAuth + API) and lib/seo/opportunities.ts
 * (filtering) — this file is the thin wrapper that ties them to the DB,
 * mirroring worker/marketing.ts over lib/marketing/discovery.ts.
 */

import { db } from "../lib/db";
import { getSettingBool, getSettingInt } from "../lib/settings";
import { resolveGscAccessToken, markGscSynced } from "../lib/seo/searchConsole";
import { fetchStrikingDistanceOpportunities } from "../lib/seo/opportunities";

export async function seoOpportunitySweep(): Promise<void> {
  // Operator kill-switch. Defaults ON: this sweep only ever reads Google's
  // authorized read-only API (webmasters.readonly) and writes to our own DB —
  // the same read-only/low-risk class as marketing_monitor_enabled, which also
  // defaults ON. A single Setting flip pauses it without a deploy. It is also
  // a natural no-op until an admin actually connects Search Console.
  if (!(await getSettingBool("seo_monitor_enabled", true))) return;

  // Tunable from Settings (see lib/actions-seo.ts / /admin/seo/settings).
  const lookbackDays = await getSettingInt("seo_lookback_days", 90);
  const minImpressions = await getSettingInt("seo_min_impressions", 15);

  let accessToken: string | undefined;
  let siteUrl: string | undefined;
  try {
    const resolved = await resolveGscAccessToken();
    accessToken = resolved.accessToken;
    siteUrl = resolved.siteUrl;
    if (!accessToken || !siteUrl) {
      // Not connected yet is the common/expected case — stay quiet. Anything
      // else (a stale connection, a resolvable-but-erroring site lookup) is
      // worth a log line so an admin investigating a stalled sweep can see it.
      if (resolved.error && !/isn't connected/i.test(resolved.error)) {
        console.error(`[seo] ${resolved.error}`);
      }
      return;
    }
  } catch (e) {
    console.error("[seo] token resolve error", e);
    return;
  }

  let opportunities;
  try {
    const result = await fetchStrikingDistanceOpportunities({ accessToken, siteUrl, lookbackDays, minImpressions });
    opportunities = result.opportunities;
    if (!opportunities) {
      console.error(`[seo] searchAnalytics query failed: ${result.error}`);
      return;
    }
  } catch (e) {
    console.error("[seo] searchAnalytics query error", e);
    return;
  }

  const now = new Date();
  let upserted = 0;
  for (const o of opportunities) {
    // Prisma's compound-unique lookup can't match a NULL `page` (Postgres
    // treats every NULL as distinct, so `{query, page: null}` would never
    // find an existing row and each sweep would insert a fresh duplicate).
    // Coerce to "" for the identity we upsert on — in practice GSC always
    // returns a real page string for the query+page dimension pair anyway;
    // the column stays nullable per the schema for any future caller that
    // queries by `query` alone.
    const page = o.page ?? "";
    try {
      await db.seoOpportunity.upsert({
        where: { query_page: { query: o.query, page } },
        update: {
          impressions: o.impressions,
          clicks: o.clicks,
          ctr: o.ctr,
          position: o.position,
          lastSeenAt: now,
        },
        create: {
          query: o.query,
          page,
          impressions: o.impressions,
          clicks: o.clicks,
          ctr: o.ctr,
          position: o.position,
          firstSeenAt: now,
          lastSeenAt: now,
        },
      });
      upserted++;
    } catch (e) {
      console.error("[seo] opportunity upsert error", e);
    }
  }

  await markGscSynced().catch(() => {});
  if (upserted > 0) {
    console.log(`[seo] upserted ${upserted} striking-distance opportunit${upserted === 1 ? "y" : "ies"}`);
  }
}

