/**
 * SEO Opportunity Discovery — pure filtering logic over Google Search Console
 * data (read-only, rate-limited to one call per sweep). Mirrors the shape of
 * lib/marketing/discovery.ts: this module only fetches + filters; the caller
 * (worker/seo.ts) owns dedupe/upsert into our own DB.
 */

import { gscQuerySearchAnalytics, type GscAnalyticsRow } from "./searchConsole";

export type StrikingDistanceOpportunity = GscAnalyticsRow;

/** Default "content gap, worth a look" ranking band — see filterStrikingDistance. */
export const DEFAULT_MIN_POSITION = 11;
export const DEFAULT_MAX_POSITION = 30;

/**
 * Filter raw searchAnalytics rows down to "striking distance" candidates:
 * demonstrated interest (impressions at/above the tunable threshold) but
 * ranking outside the top 10. Position 11–30 is the realistic "content gap,
 * worth a look" zone (task spec) — deep enough to be a real near-miss, not so
 * deep that ranking movement is implausible. Deliberately NOT trying to judge
 * whether a good page already exists for the query — that classification is a
 * human call in v1; this just surfaces the raw candidates well.
 */
export function filterStrikingDistance(
  rows: GscAnalyticsRow[],
  opts: { minImpressions: number; minPosition?: number; maxPosition?: number },
): StrikingDistanceOpportunity[] {
  const minPosition = opts.minPosition ?? DEFAULT_MIN_POSITION;
  const maxPosition = opts.maxPosition ?? DEFAULT_MAX_POSITION;
  return rows.filter(
    (r) => r.impressions >= opts.minImpressions && r.position >= minPosition && r.position <= maxPosition,
  );
}

/** Fetch the lookback window from Search Console and filter it in one call. */
export async function fetchStrikingDistanceOpportunities(opts: {
  accessToken: string;
  siteUrl: string;
  lookbackDays: number;
  minImpressions: number;
}): Promise<{ opportunities?: StrikingDistanceOpportunity[]; error?: string }> {
  const { rows, error } = await gscQuerySearchAnalytics({
    accessToken: opts.accessToken,
    siteUrl: opts.siteUrl,
    days: opts.lookbackDays,
  });
  if (!rows) return { error };
  return { opportunities: filterStrikingDistance(rows, { minImpressions: opts.minImpressions }) };
}

